def policy(obs, P):
    x = obs[0]
    y = obs[1]
    vx = obs[2]
    vy = obs[3]
    angle = obs[4]
    ang_v = obs[5]
    leg_left = obs[6]
    leg_right = obs[7]
    if (leg_left > 0.5 or leg_right > 0.5) and y < P['y_leg'] and abs(vy) < P['vy_leg'] and abs(vx) < P['vx_leg'] and abs(angle) < P['ang_leg'] and abs(ang_v) < P['av_leg']:
        return 0
    if angle < -P['a_thr']:
        return 1
    if angle > P['a_thr']:
        return 3
    if ang_v < -P['av_thr']:
        return 1
    if ang_v > P['av_thr']:
        return 3
    if vy < P['vy_main']:
        if y > P['y_high']:
            if x < -P['x_thr'] or vx < -P['vx_thr']:
                return 3
            if x > P['x_thr'] or vx > P['vx_thr']:
                return 1
            return 0
        return 2
    if vy < P['vy_low']:
        if y < P['y_mid']:
            return 2
        if x < -P['x_thr'] or vx < -P['vx_thr']:
            return 3
        if x > P['x_thr'] or vx > P['vx_thr']:
            return 1
        return 0
    if x < -P['x_thr'] or vx < -P['vx_thr']:
        return 3
    if x > P['x_thr'] or vx > P['vx_thr']:
        return 1
    if vy < P['vy_low2']:
        return 2
    return 0
